  "asayake no uta|1973": {"id":264563,"poster":"/AngrdHZOaeToRXPuaLR8XYTRvx6.jpg","title":"朝やけの詩","title_en":"Rise, Fair Sun","overview_en":"Though a farmer and his fellow villagers in this Japanese film resist the effort to turn the unspoiled region in which they live into a land development, they are ultimately unsuccessful.","kind":"movie","genre_ids":[18],"vote_average":10,"vote_count":1,"imdb_id":"tt0203316","rt_url":"https://www.rottentomatoes.com/m/rise_fair_sun","imdb_rating":8.4,"imdb_votes":21},
  "asphalt|*": {"id":55584,"poster":"/h6rvyO24kP4S9xcyERJC0qgw1pr.jpg","title":"Asphalt","title_en":"Asphalt","overview":"Der Berliner Polizeiwachtmeister Albert Holk erwischt die schöne Diebin Else auf frischer Tat bei einem Juwelendiebstahl, erliegt aber ihren Verführungskünsten und lässt sie schliesslich laufen. Die raffinierte Dame raubt dem braven Gesetzeshüter mit ihren Reizen derartig den Verstand, dass dieser blind vor Liebe und krank vor Eifersucht selbst vor Mord an einem Nebenbuhler nicht zurückschreckt...","overview_en":"Starring Betty Amann in her most famous leading role, Joe May's Asphalt is a luxuriously produced German Expressionist classic where tragic liaisons and fatal encounters are shaped alongside the constant roar of Berlin traffic.","kind":"movie","genre_ids":[18],"vote_average":7.284,"vote_count":51,"imdb_id":"tt0019655","rt_url":"https://www.rottentomatoes.com/m/asphalt/","imdb_rating":7.4,"imdb_votes":1729},
