  "cosmo corpus コスモ・コルプス|2025": {"id":1613551,"poster":"/mYBSc1fxPV9ZW0jEYbyX8TC1h1Q.jpg","title":"コスモ・コルプス","title_en":"Cosmo Corpus","overview_en":"In the distant future, humanity has split into two groups: one that has left Earth to explore the cosmos, and another that remains behind, surviving on the planet.","kind":"movie","genre_ids":[878],"vote_average":0,"vote_count":0,"imdb_id":"tt38589817"},
