  "desperate living|1977": {"id":14262,"poster":"/nVus5axqx1MBldy5RO2Rf5AEUqu.jpg","title":"Desperate Living","title_en":"Desperate Living","overview_en":"After killing her husband, Peggy Gravel and her murderous maid Grizelda wind up in the crazy town of Mortville, where Queen Carlotta presides over a sleazy collection of misfits.","kind":"movie","genre_ids":[35,80],"vote_average":6.4,"vote_count":117,"imdb_id":"tt0075936","rt_critic":70,"rt_url":"https://www.rottentomatoes.com/m/desperate_living/","imdb_rating":7,"imdb_votes":6094},
