  "ein blonder traum|*": {"id":218976,"poster":"/7JjPdkgU9HKrnG8i4gyXXftYuqA.jpg","title":"Ein blonder Traum","title_en":"A Blonde Dream","overview":"Ein blonder Traum ist eine 1932 gedrehte musikalische Komödie mit dem Traumpaar des deutschen Films der 1930er Jahre, Lilian Harvey und Willy Fritsch, sowie dem Wiener Willi Forst in den drei Hauptrollen.","overview_en":"Rival window cleaners Willy I and Willy 2 befriend Jou-Jou, an aspiring dancer, who has been tricked out of money by a con-man posing as an American movie mogul, and together they turn an old railway carriage into a \"Villa Hollywood\" for her.","kind":"movie","genre_ids":[35,10749],"vote_average":5.25,"vote_count":8,"imdb_id":"tt0022699","imdb_rating":6.3,"imdb_votes":268},
