  "royal ballet & opera live 2026/27: alice im wunderland|2026": {"id":12092,"poster":"/lCnZ7WaXwS4lVSbY2NmkqJh7D1s.jpg","title":"Alice im Wunderland","title_en":"Alice in Wonderland","overview":"Die kleine Alice folgt im Park einem weißen Kaninchen in dessen Bau und findet sich daraufhin in der eigenartigen Welt des Wunderlands wieder.","overview_en":"On a golden afternoon, wildly curious young Alice tumbles into the burrow and enters the merry, madcap world of Wonderland full of whimsical escapades.","kind":"movie","genre_ids":[16,10751,14,12],"vote_average":7.2,"vote_count":6274,"imdb_id":"tt0043274","rt_critic":82,"rt_url":"https://www.rottentomatoes.com/m/1029112-alice_in_wonderland/","imdb_rating":7.3,"imdb_votes":165367},
