  "urlaub auf ehrenwort|1938": {"id":294575,"poster":"/nAWXHO21PemUi1plsLyQNgT8PgL.jpg","title":"Urlaub auf Ehrenwort","title_en":"Furlough on Parole","overview":"Basierend auf der autobiographischen gleichnamigen Kurzgeschichte von Walter Julius Bloem jr. spielt der Film Ende 1918 in der Endphase des Ersten Weltkriegs. Ein Zug deutscher Infanteristen unter dem Kommando von Leutnant Prätorius soll an die Westfront verlegt werden","overview_en":"In 1918, a German regiment is granted five-hours leave in Berlin.","kind":"movie","genre_ids":[18,10752],"vote_average":6,"vote_count":6,"imdb_id":"tt0029722","imdb_rating":7.6,"imdb_votes":68},
  "vatanyolu - die heimreise d, keine angabe|1988": null,
  "vatanyolu - die heimreise|*": {"id":423718,"poster":"/kh38U9WE81zxV5tlixf7BvRqbR5.jpg","title":"Vatanyolu – Die Heimreise","title_en":"Vatanyolu – Die Heimreise","overview":"deutscher Spielfilm","overview_en":"In the 1960s, Yusuf returns to Turkey after 20 years in Germany, taking his family on a crowded minibus trip. His eldest son, wanting to stay and finish his training in Germany, sabotages the journey, stranding them in the woods. The family builds a new life until authorities intervene, leading to a compromise: the children stay in Germany while Yusuf and his wife return to Turkey with their youngest daughter.","kind":"movie","genre_ids":[18],"vote_average":10,"vote_count":1,"imdb_id":"tt0096367"},
  "vatanyolu - die heimreise|1988": {"id":423718,"poster":"/kh38U9WE81zxV5tlixf7BvRqbR5.jpg","title":"Vatanyolu – Die Heimreise","title_en":"Vatanyolu – Die Heimreise","overview":"deutscher Spielfilm","overview_en":"In the 1960s, Yusuf returns to Turkey after 20 years in Germany, taking his family on a crowded minibus trip. His eldest son, wanting to stay and finish his training in Germany, sabotages the journey, stranding them in the woods. The family builds a new life until authorities intervene, leading to a compromise: the children stay in Germany while Yusuf and his wife return to Turkey with their youngest daughter.","kind":"movie","genre_ids":[18],"vote_average":10,"vote_count":1,"imdb_id":"tt0096367"},
  "vater unser bestes stück|*": {"id":281666,"poster":null,"title":"Vater, unser bestes Stück","title_en":"Vater, unser bestes Stück","overview":"Vater, unser bestes Stück ist eine deutsche Filmkomödie des Regisseurs Günther Lüders. . Der Film handelt von einem hochbeständigen Eheglück und flüchtigeren Elternsorgen. Dabei wird das Gemüt vom Regisseur tapfer in Schach gehalten und die Schelmerei, zugunsten erlaubter Späße, fast ganz ausgesperrt. Ewald Balser macht aus dem kinderreichen Universitätsprofessor die Traumgestalt eines ritterlichen und arglosen Mannes.","kind":"movie","genre_ids":[35],"vote_average":5.833,"vote_count":3,"imdb_id":"tt0051153","imdb_rating":6.1,"imdb_votes":16,"overview_en":"Vater, unser bestes Stück is a German comedy film by director Günther Lüders. The movie is about a highly stable marital bliss and fleeting parental worries. The director bravely keeps the mood in check and almost completely shuts out the mischievousness in favor of permissible jokes. Ewald Balser turns the child-rich university professor into the dream figure of a chivalrous and guileless man."},
  "verflucht normal (i swear)|*": {"id":1317149,"poster":"/8V8HXyE8uiBTY1JqlQkSUHbj25D.jpg","title":"Verflucht Normal","title_en":"I Swear","overview":"Bei John Davidson wurde im Alter von 15 Jahren das Tourette-Syndrom diagnostiziert. Er kämpft sich gegen alle Widerstände durch seine schwierige Jugendzeit und bis ins Erwachsenenalter vor und findet Inspiration in der Freundlichkeit anderer, um seinen wahren Lebenssinn zu entdecken.","overview_en":"Diagnosed with Tourette Syndrome at 15, John Davidson navigates his way against the odds through troubled teenage years and into adulthood, finding inspiration in the kindness of others to discover his true purpose in life.","kind":"movie","genre_ids":[18],"vote_average":8.226,"vote_count":292,"imdb_id":"tt31514146","rt_critic":100,"imdb_rating":8.4,"imdb_votes":37223,"rt_url":"https://www.rottentomatoes.com/m/i_swear_2025"},
